import sys

def main():
    data = sys.stdin.read().split('\\n')
    if not data:
        print(\"ERR\")
        return
    idx = 0
    while idx < len(data) and data[idx].strip() == '':
        idx += 1
    if idx >= len(data):
        print(\"ERR\")
        return
    try:
        k = int(data[idx].strip())
    except ValueError:
        print(\"ERR\")
        return
    idx += 1

    prog = []
    for _ in range(k):
        if idx < len(data):
            prog.append(data[idx].strip())
            idx += 1
        else:
            prog.append('')

    steps = 0
    pc = 0
    stack = []

    while True:
        if steps >= 10000:
            print(\"ERR\")
            return
        if pc < 0 or pc >= len(prog):
            print(\"ERR\")
            return
        parts = prog[pc].split()
        if not parts:
            print(\"ERR\")
            return
        op = parts[0]
        steps += 1
        nxt = pc + 1

        if op == 'PUSH':
            if len(parts) < 2:
                print(\"ERR\"); return
            try:
                val = int(parts[1])
            except ValueError:
                print(\"ERR\"); return
            stack.append(val)
        elif op == 'POP':
            if not stack:
                print(\"ERR\"); return
            stack.pop()
        elif op == 'ADD':
            if len(stack) < 2:
                print(\"ERR\"); return
            a = stack.pop()
            b = stack.pop()
            stack.append(b + a)
        elif op == 'SUB':
            if len(stack) < 2:
                print(\"ERR\"); return
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif op == 'MUL':
            if len(stack) < 2:
                print(\"ERR\"); return
            a = stack.pop()
            b = stack.pop()
            stack.append(b * a)
        elif op == 'DUP':
            if not stack:
                print(\"ERR\"); return
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                print(\"ERR\"); return
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'PRINT':
            if not stack:
                print(\"ERR\"); return
            sys.stdout.write(str(stack.pop()) + \"\\n\")
        elif op == 'JNZ':
            if len(parts) < 2:
                print(\"ERR\"); return
            try:
                target = int(parts[1])
            except ValueError:
                print(\"ERR\"); return
            if not stack:
                print(\"ERR\"); return
            v = stack.pop()
            if v "'!= 0:
                if target < 0 or target >= len(prog):
                    print("ERR"); return
                nxt = target
        elif op == '"'HALT':
            return
        else:
            print(\"ERR\"); return
        pc = nxt

main()
